// Faithful reimplementation of Python's int(str) conversion semantics
// for argparse-style `type=int` arguments.

const PY_INT_RE = /^[+-]?\d+(?:_\d+)*$/;

/**
 * Parse a string the way Python's int(str) does (base 10):
 *  - leading/trailing whitespace is stripped
 *  - an optional single + or - sign is allowed
 *  - digits may contain single underscores between digit groups
 * Returns a Number on success, or null when Python would raise ValueError.
 */
export function parsePythonInt(raw) {
  const s = String(raw).trim();
  if (!PY_INT_RE.test(s)) {
    return null;
  }
  const normalized = s.replace(/_/g, "");
  const value = Number.parseInt(normalized, 10);
  if (!Number.isSafeInteger(value)) {
    return null;
  }
  return value;
}

