// Minimal argparse-compatible parser, matching the observable behavior of
// Python's argparse for the options used by test3.py:
//   --a (int, required), --b (str, required), -h/--help
// Error/usage/help text and exit codes mirror CPython's argparse.

import { basename } from "node:path";
import { parsePythonInt } from "./pyint.mjs";

// A token that looks like a negative number is accepted as a value by
// argparse when the parser has no options that look like negative numbers.
const NEGATIVE_NUMBER_RE = /^-\d+$/;

function looksLikeOption(token) {
  if (!token.startsWith("-") || token === "-") {
    return false;
  }
  return !NEGATIVE_NUMBER_RE.test(token);
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
  }

  usage() {
    return `usage: ${this.prog} [-h] --a A --b B`;
  }

  helpText() {
    return `${this.usage()}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`;
  }

  fail(message) {
    process.stderr.write(`${this.usage()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv) {
    const result = { a: undefined, b: undefined };
    const extras = [];

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (token === "-h" || token === "--help") {
        process.stdout.write(`${this.helpText()}\n`);
        process.exit(0);
      }

      // Split "--opt=value" form.
      let name = token;
      let inlineValue = null;
      const eq = token.indexOf("=");
      if (token.startsWith("--") && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      if (name === "--a" || name === "--b") {
        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
          i += 1;
          raw = argv[i];
        } else {
          this.fail(`argument ${name}: expected one argument`);
        }

        if (name === "--a") {
          const parsed = parsePythonInt(raw);
          if (parsed === null) {
            this.fail(`argument --a: invalid int value: '${raw}'`);
          }
          result.a = parsed;
        } else {
          result.b = raw;
        }
      } else {
        extras.push(token);
      }
    }

    const missing = [];
    if (result.a === undefined) missing.push("--a");
    if (result.b === undefined) missing.push("--b");
    if (missing.length > 0) {
      this.fail(`the following arguments are required: ${missing.join(", ")}`);
    }

    if (extras.length > 0) {
      this.fail(`unrecognized arguments: ${extras.join(" ")}`);
    }

    return result;
  }
}

/**
 * Parse process.argv-style arguments (without node/script prefix),
 * mirroring `argparse` with prog derived from the entry script name.
 */
export function parseCliArgs(argv, scriptPath) {
  const prog = basename(scriptPath || "test3.mjs");
  return new ArgumentParser(prog).parseArgs(argv);
}

