// Minimal black-box reimplementation of the `schedule` package surface
// used by test3.py: schedule.every(n).minutes -> Job with .interval === n.

export class Job {
  constructor(interval, unit = null) {
    this.interval = interval;
    this.unit = unit;
  }

  get minutes() {
    this.unit = "minutes";
    return this;
  }
}

/**
 * Mirror of schedule.every(interval): returns a Job whose `interval`
 * equals the given value; accessing `.minutes` keeps the same interval.
 */
export function every(interval) {
  return new Job(interval);
}

