// Entry point — ESM equivalent of test3.py.
// Mirrors: argparse with --a (int, required) / --b (str, required),
// then `schedule.every(args.a).minutes` and printing `job.interval`.

import { fileURLToPath } from "node:url";
import { parseCliArgs } from "./lib/argparser.mjs";
import { every } from "./lib/schedule.mjs";

const args = parseCliArgs(process.argv.slice(2), fileURLToPath(import.meta.url));

const job = every(args.a).minutes; // 创建分钟间隔作业
console.log(job.interval);

